package net.officefloor.hq.app.person;

import java.util.Comparator;
import java.util.List;
import java.util.NoSuchElementException;
import java.util.Optional;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.pool.PoolMember;
import net.officefloor.hq.app.pool.PoolMemberRepository;
import net.officefloor.hq.app.setting.Role;
import net.officefloor.hq.app.setting.SettingService;
import net.officefloor.hq.app.sheet.SheetService;
import net.officefloor.hq.app.statement.StatementRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/** Merges a person into another on the same sheet: the merged person leaves the sheet and the other
 *  takes on their claims, names, patrons and pool memberships. */
@Service
public class PersonMergeService {

    private final PersonRepository people;
    private final PersonAliasRepository aliases;
    private final PersonPatronRepository patrons;
    private final PersonHoldRepository holds;
    private final PersonWatchRepository watches;
    private final ClaimRepository claims;
    private final StatementRepository statements;
    private final PoolMemberRepository poolMembers;
    private final SettingService settings;
    private final SheetService sheets;
    private final Audit audit;

    public PersonMergeService(PersonRepository people, PersonAliasRepository aliases, PersonPatronRepository patrons,
            PersonHoldRepository holds, PersonWatchRepository watches, ClaimRepository claims,
            StatementRepository statements, PoolMemberRepository poolMembers, SettingService settings,
            SheetService sheets, Audit audit) {
        this.people = people;
        this.aliases = aliases;
        this.patrons = patrons;
        this.holds = holds;
        this.watches = watches;
        this.claims = claims;
        this.statements = statements;
        this.poolMembers = poolMembers;
        this.settings = settings;
        this.sheets = sheets;
        this.audit = audit;
    }

    /** A steward merges a person into another. The merged person's claims move to the other, keeping
     *  their numbers and dates, listed as the other's newest in the order they were added, each losing
     *  any figure a statement bound; the merged name and aliases become the other's aliases; the merged
     *  person's patrons are added to the other's (not the other themselves, no repeats), anyone naming
     *  the merged person as patron names the other instead (no repeats), and the merged person's pool
     *  memberships move to the other (shares added where the other is already a member). Their
     *  statements, holds, watchers and contact are dropped, and they leave the sheet. Anyone but a
     *  steward, a merge into the same person, or either of them retired, is refused. Returns the other. */
    @Transactional
    public Person merge(String sheetId, String user, Long id, Long intoId) {
        sheets.lock(sheetId);
        Person from = person(sheetId, id);
        Person into = person(sheetId, intoId);
        if (settings.roleOf(sheetId, user) != Role.STEWARD) {
            throw new MergeRefusedException(user + " is not a steward: only a steward merges people");
        }
        if (from.getId().equals(into.getId())) {
            throw new MergeRefusedException(from.getName() + " cannot be merged into themselves");
        }
        if (from.isRetired() || into.isRetired()) {
            throw new MergeRefusedException("A retired person is neither merged nor merged into");
        }
        absorb(sheetId, user, from, into);
        return into;
    }

    /** Merges one person into another on the sheet, as {@link #merge} does once it is allowed: a person
     *  transferred onto a sheet that has them already by a name or alias is merged this way. */
    void absorb(String sheetId, String user, Person from, Person into) {

        List<Claim> moved = claims.findBySheetIdAndPersonIdOrderByListedDesc(sheetId, from.getId()).stream()
                .sorted(Comparator.comparing(Claim::getId)).toList();
        for (Claim claim : moved) {
            claim.setPersonId(into.getId());
            claim.unbind();
        }
        claims.saveAllAndFlush(moved);
        moved.forEach(claim -> claims.relist(claim.getId()));

        List<PersonAlias> theirAliases = aliases.findByPersonIdOrderByIdAsc(from.getId());
        theirAliases.forEach(alias -> alias.setPersonId(into.getId()));
        aliases.saveAllAndFlush(theirAliases);
        aliases.saveAndFlush(new PersonAlias(sheetId, into.getId(), from.getName(), sheets.today(sheetId)));

        List<PersonPatron> theirPatrons = patrons.findByPersonIdOrderByIdAsc(from.getId());
        patrons.deleteAll(theirPatrons);
        patrons.flush();
        for (PersonPatron patron : theirPatrons) {
            Long patronId = patron.getPatronId();
            if (!patronId.equals(into.getId()) && !patrons.existsByPersonIdAndPatronId(into.getId(), patronId)) {
                patrons.saveAndFlush(new PersonPatron(sheetId, into.getId(), patronId, sheets.today(sheetId)));
            }
        }
        for (PersonPatron naming : patrons.findBySheetIdOrderByIdAsc(sheetId)) {
            if (!naming.getPatronId().equals(from.getId())) {
                continue;
            }
            if (naming.getPersonId().equals(into.getId())
                    || patrons.existsByPersonIdAndPatronId(naming.getPersonId(), into.getId())) {
                patrons.delete(naming);
                patrons.flush();
            } else {
                naming.setPatronId(into.getId());
                patrons.saveAndFlush(naming);
            }
        }

        for (PoolMember member : poolMembers.findByPersonIdOrderByIdAsc(from.getId())) {
            Optional<PoolMember> already = poolMembers.findByPoolIdAndPersonId(member.getPoolId(), into.getId());
            if (already.isPresent()) {
                already.get().addShare(member.getShare());
                poolMembers.delete(member);
                poolMembers.flush();
                poolMembers.saveAndFlush(already.get());
            } else {
                member.setPersonId(into.getId());
                poolMembers.saveAndFlush(member);
            }
        }

        statements.deleteAll(statements.findBySheetIdAndPersonIdOrderByIdAsc(sheetId, from.getId()));
        holds.deleteAll(holds.findByPersonIdOrderByIdAsc(from.getId()));
        watches.deleteAll(watches.findByPersonIdOrderByIdAsc(from.getId()));
        from.setContact(null);
        from.mergeInto(into.getId());
        people.saveAndFlush(from);

        audit.recordOnCommit("PERSON_MERGED sheet=" + sheetId + " by=" + user + " from=" + from.getName()
                + " into=" + into.getName());
    }

    private Person person(String sheetId, Long id) {
        return people.findByIdAndSheetId(id, sheetId)
                .orElseThrow(() -> new NoSuchElementException("No person " + id + " on sheet " + sheetId));
    }
}
package net.officefloor.hq.app.person;

import jakarta.persistence.EntityManager;
import java.time.LocalDate;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.NoSuchElementException;
import java.util.Optional;
import java.util.stream.Stream;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimLogEntry;
import net.officefloor.hq.app.claim.ClaimLogRepository;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.claim.ClaimService;
import net.officefloor.hq.app.claim.ClaimStatus;
import net.officefloor.hq.app.history.History;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.setting.Role;
import net.officefloor.hq.app.setting.SettingService;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/** Transfers a person to another sheet: they arrive there with their grades, terms, contact, aliases
 *  and claims, and leave this sheet entirely. */
@Service
public class PersonTransferService {

    private final PersonRepository people;
    private final PersonAliasRepository aliases;
    private final ClaimRepository claims;
    private final ClaimLogRepository logs;
    private final ClaimService claimService;
    private final RollupService rollups;
    private final SettingService settings;
    private final SheetService sheets;
    private final History history;
    private final JdbcTemplate jdbc;
    private final EntityManager entities;
    private final PersonMergeService merges;
    private final Audit audit;

    public PersonTransferService(PersonRepository people, PersonAliasRepository aliases, ClaimRepository claims,
            ClaimLogRepository logs, ClaimService claimService, RollupService rollups, SettingService settings,
            SheetService sheets, History history, JdbcTemplate jdbc, EntityManager entities, PersonMergeService merges,
            Audit audit) {
        this.people = people;
        this.aliases = aliases;
        this.claims = claims;
        this.logs = logs;
        this.claimService = claimService;
        this.rollups = rollups;
        this.settings = settings;
        this.sheets = sheets;
        this.history = history;
        this.jdbc = jdbc;
        this.entities = entities;
        this.merges = merges;
        this.audit = audit;
    }

    /** A steward transfers a person to another sheet by id. The person arrives there with every grade
     *  they were given, their terms, contact and aliases, and their claims with their status, dates,
     *  notes, tags, frozen figures and logs; each claim that had a number takes the other sheet's next
     *  number, in the order the claims were opened (by the sheet's today when each was, then the order
     *  they were added). Figures a statement bound are lost with the statements, references, comments
     *  and settle batches are not carried; patron links, pool memberships, holds and watches are
     *  dropped. A person the other sheet already has by their name or an alias (as names are compared)
     *  arrives and is then merged into them, as a merge does. Anyone but a steward, a retired person,
     *  this sheet's own id, an archived sheet, a name or alias matching more than one person or a
     *  retired one there, or (when not merged) a name, alias or contact already on the other sheet, is
     *  refused. Each sheet writes its line,
     *  followed by its rollup lines. */
    @Transactional
    public void transfer(String sheetId, String user, Long id, String toSheetId) {
        String to = toSheetId == null ? "" : toSheetId.trim();
        if (to.isEmpty() || to.length() > 200) {
            throw new TransferRefusedException("A sheet id to transfer to is needed");
        }
        // Lock both sheets in one order, so transfers between them made at the same moment wait.
        Stream.of(sheetId, to).sorted().distinct().forEach(sheets::lock);
        rollups.track(sheetId, user, () -> rollups.track(to, user, () -> {
            move(sheetId, user, id, to);
            return null;
        }));
    }

    private void move(String sheetId, String user, Long id, String to) {
        Person person = people.findByIdAndSheetId(id, sheetId)
                .orElseThrow(() -> new NoSuchElementException("No person " + id + " on sheet " + sheetId));
        if (settings.roleOf(sheetId, user) != Role.STEWARD) {
            throw new TransferRefusedException(user + " is not a steward: only a steward transfers people");
        }
        if (person.isRetired()) {
            throw new TransferRefusedException("A retired person is not transferred");
        }
        if (to.equals(sheetId)) {
            throw new TransferRefusedException(person.getName() + " is on " + sheetId + " already");
        }
        if (sheets.isArchived(sheetId) || sheets.isArchived(to)) {
            throw new TransferRefusedException("An archived sheet takes no transfer");
        }
        List<PersonAlias> theirAliases = aliases.findByPersonIdOrderByIdAsc(person.getId());
        List<String> theirNames = Stream.concat(Stream.of(person.getName()),
                theirAliases.stream().map(PersonAlias::getAlias)).toList();
        List<Long> sameNamed = theirNames.stream().map(name -> people.findByName(to, name))
                .flatMap(Optional::stream).map(Person::getId).distinct().toList();
        Long intoId = null;
        if (sameNamed.size() > 1) {
            throw new NameInUseException(person.getName());
        } else if (sameNamed.size() == 1) {
            // Already on the other sheet by a name or alias: they arrive and are merged into them.
            intoId = sameNamed.get(0);
            if (people.findById(intoId).orElseThrow().isRetired()) {
                throw new TransferRefusedException("A retired person is not merged into");
            }
        } else {
            boolean nameTaken = theirNames.stream()
                    .anyMatch(name -> people.nameInUse(to, name, null) || aliases.aliasInUse(to, name));
            if (nameTaken) {
                throw new NameInUseException(person.getName());
            }
            if (person.getContact() != null && people.contactInUse(to, person.getContact(), null)) {
                throw new ContactInUseException(person.getContact());
            }
        }

        List<Claim> theirClaims = claims.findBySheetIdAndPersonIdOrderByListedDesc(sheetId, person.getId());
        Map<Long, LocalDate> openedOn = new HashMap<>();
        for (Claim claim : theirClaims) {
            logs.findByClaimIdOrderByIdAsc(claim.getId()).stream()
                    .filter(line -> line.getStatus() == ClaimStatus.OPEN).map(ClaimLogEntry::getOn).findFirst()
                    .ifPresent(on -> openedOn.put(claim.getId(), on));
        }
        List<Claim> numbered = theirClaims.stream().filter(claim -> claim.getNumber() != null)
                .sorted(Comparator.comparing((Claim claim) -> openedOn.getOrDefault(claim.getId(), LocalDate.MAX))
                        .thenComparing(Claim::getId))
                .toList();
        Map<String, String> oldNumbers = new HashMap<>();
        numbered.forEach(claim -> oldNumbers.put(String.valueOf(claim.getId()), claim.getNumber()));
        List<String> tags = Stream.concat(person.getTags().stream(),
                theirClaims.stream().flatMap(claim -> claim.getTags().stream())).distinct().toList();
        LocalDate today = sheets.today(to);
        Long personId = person.getId();
        entities.flush();

        // Left behind on this sheet: patron links both ways, pool memberships, holds, watches,
        // statements, and the claims' comments.
        jdbc.update("DELETE FROM person_patron WHERE person_id = ? OR patron_id = ?", personId, personId);
        jdbc.update("DELETE FROM pool_member WHERE person_id = ?", personId);
        jdbc.update("DELETE FROM person_hold WHERE person_id = ?", personId);
        jdbc.update("DELETE FROM person_watch WHERE person_id = ?", personId);
        jdbc.update("DELETE FROM statement WHERE person_id = ?", personId);
        jdbc.update("DELETE FROM claim_comment WHERE claim_id IN (SELECT id FROM claim WHERE person_id = ?)",
                personId);

        // Carried to the other sheet: the person, their grades, aliases and claims with their logs.
        jdbc.update("UPDATE person SET sheet_id = ?, added_on = ?, origin_sheet_id = ? WHERE id = ?", to, today,
                sheetId, personId);
        jdbc.update("UPDATE person_grade SET sheet_id = ? WHERE person_id = ?", to, personId);
        jdbc.update("UPDATE person_alias SET sheet_id = ? WHERE person_id = ?", to, personId);
        jdbc.update("UPDATE claim SET sheet_id = ?, claim_number = NULL, ref = NULL, ref_key = NULL, stated = FALSE,"
                + " stated_due = NULL, settle_batch = NULL, locked_by = NULL WHERE person_id = ?", to, personId);
        jdbc.update("UPDATE claim_status_log SET sheet_id = ? WHERE claim_id IN (SELECT id FROM claim WHERE"
                + " person_id = ?)", to, personId);
        entities.clear();

        Map<String, String> newNumbers = new HashMap<>();
        for (Claim was : numbered) {
            Claim claim = claims.findById(was.getId()).orElseThrow();
            String number = claimService.numberFor(to, claim.getDueBy());
            newNumbers.put(oldNumbers.get(String.valueOf(claim.getId())), number);
            claim.setNumber(number);
            claims.saveAndFlush(claim);
        }
        for (Claim was : theirClaims) {
            Claim claim = claims.findById(was.getId()).orElseThrow();
            if (claim.getCorrects() != null) {
                claim.setCorrects(newNumbers.get(claim.getCorrects()));
                claims.saveAndFlush(claim);
            }
            if (claim.getSplitFrom() != null) {
                jdbc.update("UPDATE claim SET split_from = ? WHERE id = ?", newNumbers.get(claim.getSplitFrom()),
                        claim.getId());
            }
            history.claimKept(claim.getId());
        }
        history.personKept(personId);
        tags.forEach(tag -> claims.useTag(to, tag));
        entities.clear();

        audit.recordOnCommit("PERSON_TRANSFERRED sheet=" + sheetId + " by=" + user + " name=" + person.getName()
                + " to=" + to);
        audit.recordOnCommit("PERSON_TRANSFERRED sheet=" + to + " by=" + user + " name=" + person.getName()
                + " from=" + sheetId);
        if (intoId != null) {
            merges.absorb(to, user, people.findById(personId).orElseThrow(), people.findById(intoId).orElseThrow());
        }
    }
}

